{"question": "Write a SQL query to detect anomalies in server response times. Flag any request where the response time is more than 2 standard deviations above the mean for that specific endpoint.", "answer": "WITH endpoint_stats AS (
  SELECT endpoint, AVG(response_time) as mean_time, STDDEV(response_time) as std_time
  FROM server_logs
  GROUP BY endpoint
)
SELECT sl.id, sl.endpoint, sl.response_time, es.mean_time, es.std_time
FROM server_logs sl
JOIN endpoint_stats es ON sl.endpoint = es.endpoint
WHERE sl.response_time > es.mean_time + (2 * es.std_time);
", "subject": "Database", "category": "SQL Generation"}
{"question": "Create a SQL query to generate a hierarchical report of employees and their managers. Include employee_name, manager_name, and level (0 for CEO, 1 for direct reports, etc.).", "answer": "WITH RECURSIVE employee_hierarchy AS (
  SELECT id, name, manager_id, 0 as level
  FROM employees
  WHERE manager_id IS NULL
  UNION ALL
  SELECT e.id, e.name, e.manager_id, eh.level + 1
  FROM employees e
  JOIN employee_hierarchy eh ON e.manager_id = eh.id
)
SELECT eh.name as employee_name, m.name as manager_name, eh.level
FROM employee_hierarchy eh
